// =====================================================
// موتور ساخت فیش حقوقی رسمی (Excel) — صبا تجهیز لاله پارسه
// این فایل جدا از app.js است و باید بعد از app.js لود شود
// چون از توابع stlpZip / stlpDownloadBlob استفاده می‌کند
//
// قالب اصلی همان فایل اکسل رسمی شرکت است (فیش حقوقی)؛
// این موتور فقط سلول‌های متغیر را با اطلاعات هر کارمند
// پر می‌کند و باقی ظاهر/استایل/فرمول‌های فایل اصلی
// دست‌نخورده باقی می‌مانند.
// =====================================================

const STLP_PAYSLIP_STYLES_B64 = "";
const STLP_PAYSLIP_THEME_B64 = "";
const STLP_PAYSLIP_SHARED_STRINGS_B64 = "";
const STLP_PAYSLIP_SHEET_TEMPLATE_B64 = "";
const STLP_PAYSLIP_LOGO_B64 = "";



// =====================================================
// تبدیل Base64 به بایت (برای فایل‌های داخل zip)
// =====================================================

function stlpPayslipBase64ToBytes(b64) {

    const binary = atob(b64);
    const bytes = new Uint8Array(binary.length);

    for (let i = 0; i < binary.length; i++) {
        bytes[i] = binary.charCodeAt(i);
    }

    return bytes;

}

function stlpPayslipBytesToText(bytes) {

    return new TextDecoder("utf-8").decode(bytes);

}


// =====================================================
// اسکیپ کردن متن برای XML
// =====================================================

function stlpPayslipXmlEsc(value) {

    return String(value == null ? "" : value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;");

}


// =====================================================
// جایگزین کردن مقدار یک سلول در XML شیت
// (سبک/فرمت سلول اصلی حفظ می‌شود، فقط مقدار عوض می‌شود)
// =====================================================

function stlpPayslipReplaceCell(xml, ref, buildReplacement) {

    const openTag = '<c r="' + ref + '"';
    const start = xml.indexOf(openTag);

    if (start === -1) {
        console.warn("⚠️ سلول در قالب فیش حقوقی پیدا نشد:", ref);
        return xml;
    }

    const gt = xml.indexOf(">", start);

    let end;

    if (xml[gt - 1] === "/") {

        // سلول خودبسته: <c r="X" .../>
        end = gt + 1;

    } else {

        // سلول با محتوا: <c r="X" ...>...</c>
        const closeTag = xml.indexOf("</c>", gt);
        end = closeTag + 4;

    }

    const tagPart = xml.substring(start, gt + 1);

    const styleMatch = tagPart.match(/\ss="(\d+)"/);

    const style = styleMatch ? styleMatch[1] : "0";

    const replacement = buildReplacement(style);

    return xml.substring(0, start) + replacement + xml.substring(end);

}


function stlpPayslipSetNumber(xml, ref, value) {

    return stlpPayslipReplaceCell(xml, ref, function(style) {

        const num = Number(value) || 0;

        return '<c r="' + ref + '" s="' + style + '"><v>' + num + '</v></c>';

    });

}


function stlpPayslipSetText(xml, ref, text) {

    return stlpPayslipReplaceCell(xml, ref, function(style) {

        if (!text) {
            return '<c r="' + ref + '" s="' + style + '"/>';
        }

        return (
            '<c r="' + ref + '" s="' + style + '" t="inlineStr">' +
            "<is><t xml:space=\"preserve\">" +
            stlpPayslipXmlEsc(text) +
            "</t></is></c>"
        );

    });

}


// =====================================================
// پر کردن یک شیت فیش حقوقی با اطلاعات یک کارمند
// data شامل فیلدهای زیر است (هرکدام نبود، صفر/خالی در نظر
// گرفته می‌شود):
//
// employeeName, position, personnelNo, date,
// monthName, year,
// workDays, leaveUsed, overtimeHours, leaveRemaining,
// nightShiftHours, shiftWorkHours, missionDays, workDeduction,
// baseSalary, seniorityBase, attractionAllowance,
// responsibilityAllowance, overtimeAmount, housingAllowance,
// childAllowance, foodAllowance, maritalAllowance, shiftWorkPay,
// missionAllowance, otherBenefits,
// advance, loan, tax, insurance, otherDeductions
// =====================================================

function stlpBuildPayslipSheetXml(templateXml, data) {

    let xml = templateXml;

    // پاک کردن متن جای‌نگه‌دار "logo" چون عکس واقعی رویش قرار می‌گیرد
    xml = stlpPayslipSetText(xml, "B1", "");

    xml = stlpPayslipSetText(xml, "J2", data.date || "");
    xml = stlpPayslipSetText(xml, "C4", data.employeeName || "");
    xml = stlpPayslipSetText(xml, "I4", data.position || "");
    xml = stlpPayslipSetText(xml, "C5", data.personnelNo || "");
    xml = stlpPayslipSetText(xml, "I5", data.monthName || "");
    xml = stlpPayslipSetNumber(xml, "K5", data.year || 0);

    xml = stlpPayslipSetNumber(xml, "D7", data.workDays || 0);
    xml = stlpPayslipSetNumber(xml, "I7", data.leaveUsed || 0);
    xml = stlpPayslipSetNumber(xml, "D8", data.overtimeHours || 0);
    xml = stlpPayslipSetNumber(xml, "I8", data.leaveRemaining || 0);
    xml = stlpPayslipSetNumber(xml, "D9", data.nightShiftHours || 0);
    xml = stlpPayslipSetNumber(xml, "I9", data.shiftWorkHours || 0);
    xml = stlpPayslipSetNumber(xml, "D10", data.missionDays || 0);
    xml = stlpPayslipSetNumber(xml, "I10", data.workDeduction || 0);

    xml = stlpPayslipSetNumber(xml, "D13", data.baseSalary || 0);
    xml = stlpPayslipSetNumber(xml, "D14", data.seniorityBase || 0);
    xml = stlpPayslipSetNumber(xml, "D15", data.attractionAllowance || 0);
    xml = stlpPayslipSetNumber(xml, "D16", data.responsibilityAllowance || 0);
    xml = stlpPayslipSetNumber(xml, "D17", data.overtimeAmount || 0);
    xml = stlpPayslipSetNumber(xml, "D18", data.housingAllowance || 0);
    xml = stlpPayslipSetNumber(xml, "D19", data.childAllowance || 0);
    xml = stlpPayslipSetNumber(xml, "D20", data.foodAllowance || 0);
    xml = stlpPayslipSetNumber(xml, "D21", data.maritalAllowance || 0);
    xml = stlpPayslipSetNumber(xml, "D22", data.shiftWorkPay || 0);
    xml = stlpPayslipSetNumber(xml, "D23", data.missionAllowance || 0);
    xml = stlpPayslipSetNumber(xml, "D24", data.otherBenefits || 0);

    xml = stlpPayslipSetNumber(xml, "I13", data.advance || 0);
    xml = stlpPayslipSetNumber(xml, "I14", data.loan || 0);
    xml = stlpPayslipSetNumber(xml, "I15", data.tax || 0);
    xml = stlpPayslipSetNumber(xml, "I16", data.insurance || 0);
    xml = stlpPayslipSetNumber(xml, "I17", data.otherDeductions || 0);

    return xml;

}


// =====================================================
// نام ماه شمسی از روی شماره ماه (۱ تا ۱۲)
// =====================================================

const STLP_PERSIAN_MONTH_NAMES = [
    "فروردین", "اردیبهشت", "خرداد", "تیر", "مرداد", "شهریور",
    "مهر", "آبان", "آذر", "دی", "بهمن", "اسفند"
];

function stlpPersianMonthName(monthNumber) {

    const idx = Number(monthNumber) - 1;

    if (idx >= 0 && idx < 12) {
        return STLP_PERSIAN_MONTH_NAMES[idx];
    }

    return "";

}


// =====================================================
// ساخت فایل اکسل فیش حقوقی برای یک یا چند کارمند
// (هر کارمند = یک شیت جدا، با نام کارمند، در یک فایل)
//
// employeesData: آرایه‌ای از data (همان ساختار بالا)
// + یک فیلد اضافه sheetName (نام شیت، معمولاً نام کارمند)
// =====================================================

async function stlpGeneratePayslipXlsx(employeesData) {

    if (!Array.isArray(employeesData) || employeesData.length === 0) {
        throw new Error("هیچ کارمندی برای ساخت فیش انتخاب نشده است.");
    }

    const templateXml =
        stlpPayslipBytesToText(
            stlpPayslipBase64ToBytes(STLP_PAYSLIP_SHEET_TEMPLATE_B64)
        );

    const encoder = new TextEncoder();

    const usedNames = {};

    const sheetEntries = employeesData.map(function(data, idx) {

        let safeName =
            String(data.sheetName || data.employeeName || ("کارمند" + (idx + 1)))
                .replace(/[\\\/\?\*\[\]:]/g, "_")
                .substring(0, 28)
                .trim() || ("کارمند" + (idx + 1));

        // جلوگیری از تکراری شدن نام شیت
        let finalName = safeName;
        let counter = 2;

        while (usedNames[finalName]) {
            finalName = (safeName + "_" + counter).substring(0, 31);
            counter++;
        }

        usedNames[finalName] = true;

        let sheetXml =
            stlpBuildPayslipSheetXml(templateXml, data);

        // اضافه کردن ارجاع به تصویر لوگو (drawing) قبل از بسته شدن worksheet
        sheetXml = sheetXml.replace(
            "</worksheet>",
            '<drawing r:id="rIdLogoDrawing"/></worksheet>'
        );

        return {
            id: idx + 1,
            name: finalName,
            xml: sheetXml
        };

    });


    const N = sheetEntries.length;

    const stylesRid = "rId" + (N + 1);
    const themeRid = "rId" + (N + 2);
    const sharedRid = "rId" + (N + 3);


    const sheetsListXml =
        sheetEntries.map(function(s) {

            return (
                '<sheet name="' + stlpPayslipXmlEsc(s.name) + '" ' +
                'sheetId="' + s.id + '" r:id="rId' + s.id + '"/>'
            );

        }).join("");


    const workbookXml =
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
        '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" ' +
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">' +
        "<sheets>" + sheetsListXml + "</sheets>" +
        "</workbook>";


    const sheetRelsXml =
        sheetEntries.map(function(s) {

            return (
                '<Relationship Id="rId' + s.id + '" ' +
                'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" ' +
                'Target="worksheets/sheet' + s.id + '.xml"/>'
            );

        }).join("");


    const workbookRelsXml =
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
        sheetRelsXml +
        '<Relationship Id="' + stylesRid + '" ' +
        'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" ' +
        'Target="styles.xml"/>' +
        '<Relationship Id="' + themeRid + '" ' +
        'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme" ' +
        'Target="theme/theme1.xml"/>' +
        '<Relationship Id="' + sharedRid + '" ' +
        'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/sharedStrings" ' +
        'Target="sharedStrings.xml"/>' +
        "</Relationships>";


    const sheetOverridesXml =
        sheetEntries.map(function(s) {

            return (
                '<Override PartName="/xl/worksheets/sheet' + s.id + '.xml" ' +
                'ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
            );

        }).join("");


    const drawingOverridesXml =
        sheetEntries.map(function(s) {

            return (
                '<Override PartName="/xl/drawings/drawing' + s.id + '.xml" ' +
                'ContentType="application/vnd.openxmlformats-officedocument.drawing+xml"/>'
            );

        }).join("");


    const contentTypesXml =
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
        '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">' +
        '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>' +
        '<Default Extension="xml" ContentType="application/xml"/>' +
        '<Default Extension="png" ContentType="image/png"/>' +
        '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>' +
        sheetOverridesXml +
        drawingOverridesXml +
        '<Override PartName="/xl/theme/theme1.xml" ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/>' +
        '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>' +
        '<Override PartName="/xl/sharedStrings.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sharedStrings+xml"/>' +
        "</Types>";


    const rootRelsXml =
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
        '<Relationship Id="rId1" ' +
        'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" ' +
        'Target="xl/workbook.xml"/>' +
        "</Relationships>";


    const files = {

        "[Content_Types].xml": encoder.encode(contentTypesXml),
        "_rels/.rels": encoder.encode(rootRelsXml),
        "xl/workbook.xml": encoder.encode(workbookXml),
        "xl/_rels/workbook.xml.rels": encoder.encode(workbookRelsXml),
        "xl/styles.xml": stlpPayslipBase64ToBytes(STLP_PAYSLIP_STYLES_B64),
        "xl/theme/theme1.xml": stlpPayslipBase64ToBytes(STLP_PAYSLIP_THEME_B64),
        "xl/sharedStrings.xml": stlpPayslipBase64ToBytes(STLP_PAYSLIP_SHARED_STRINGS_B64),
        "xl/media/image1.png": stlpPayslipBase64ToBytes(STLP_PAYSLIP_LOGO_B64)

    };

    sheetEntries.forEach(function(s) {

        files["xl/worksheets/sheet" + s.id + ".xml"] = encoder.encode(s.xml);

        // نگاشت هر شیت به drawing خودش (لوگو)
        files["xl/worksheets/_rels/sheet" + s.id + ".xml.rels"] = encoder.encode(
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
            '<Relationship Id="rIdLogoDrawing" ' +
            'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/drawing" ' +
            'Target="../drawings/drawing' + s.id + '.xml"/>' +
            "</Relationships>"
        );

        // drawing هر شیت - لوگو در محدوده B1:D3 (بدون کش‌آمدگی، اندازه ثابت)
        files["xl/drawings/drawing" + s.id + ".xml"] = encoder.encode(
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
            '<xdr:wsDr xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing" ' +
            'xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main">' +
            '<xdr:oneCellAnchor>' +
            '<xdr:from><xdr:col>1</xdr:col><xdr:colOff>19050</xdr:colOff>' +
            '<xdr:row>0</xdr:row><xdr:rowOff>19050</xdr:rowOff></xdr:from>' +
            '<xdr:ext cx="933450" cy="762000"/>' +
            '<xdr:pic>' +
            '<xdr:nvPicPr>' +
            '<xdr:cNvPr id="2" name="Logo"/>' +
            '<xdr:cNvPicPr><a:picLocks noChangeAspect="1"/></xdr:cNvPicPr>' +
            '</xdr:nvPicPr>' +
            '<xdr:blipFill>' +
            '<a:blip r:embed="rIdLogoImage" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"/>' +
            '<a:stretch><a:fillRect/></a:stretch>' +
            '</xdr:blipFill>' +
            '<xdr:spPr>' +
            '<a:xfrm><a:off x="0" y="0"/><a:ext cx="933450" cy="762000"/></a:xfrm>' +
            '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom>' +
            '</xdr:spPr>' +
            '</xdr:pic>' +
            '<xdr:clientData/>' +
            '</xdr:oneCellAnchor>' +
            '</xdr:wsDr>'
        );

        // نگاشت drawing به فایل عکس مشترک
        files["xl/drawings/_rels/drawing" + s.id + ".xml.rels"] = encoder.encode(
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
            '<Relationship Id="rIdLogoImage" ' +
            'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" ' +
            'Target="../media/image1.png"/>' +
            "</Relationships>"
        );

    });


    if (typeof stlpZip !== "function") {
        throw new Error("ماژول stlpZip (از app.js) در دسترس نیست. لطفاً مطمئن شوید app.js قبل از این فایل لود شده است.");
    }

    const zipped = stlpZip(files);

    return new Blob(
        [zipped],
        { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" }
    );

}


// =====================================================
// تابع کمکی: ساخت و دانلود مستقیم فایل فیش حقوقی
// =====================================================

async function stlpDownloadPayslipXlsx(employeesData, filename) {

    const blob = await stlpGeneratePayslipXlsx(employeesData);

    if (typeof stlpDownloadBlob === "function") {

        stlpDownloadBlob(
            blob,
            filename || ("فیش-حقوقی-" + new Date().toISOString().slice(0, 10) + ".xlsx")
        );

    } else {

        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = filename || "فیش-حقوقی.xlsx";
        document.body.appendChild(a);
        a.click();
        setTimeout(function() {
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        }, 1500);

    }

}
